// Datos INVENTADOS: nueve pedidos de un depósito, en pallets. El camión lleva 12.
function camionesNecesarios(pedidos, capacidad) {
  let camiones = 1;
  let carga = 0;
  for (let i = 0; i < pedidos.length; i++) {
    const p = pedidos[i];
    if (carga + p > capacidad) {
      camiones++;
      carga = 0;
      continue;
    }
    carga += p;
  }
  return camiones;
}

