function camionesNecesarios(pedidos, capacidad, corregido) {
  let camiones = 1, carga = 0, cargado = 0;
  for (const p of pedidos) {
    if (carga + p > capacidad) {
      camiones++;
      carga = 0;
      if (!corregido) continue;      // la línea del bug
    }
    carga += p;
    cargado += p;
  }
  const total = pedidos.reduce((a, b) => a + b, 0);
  if (cargado !== total) {
    throw new Error(`se cargaron ${cargado} pallets y había ${total}`);
  }
  return camiones;
}

