#include <pthread.h>
#include <stdio.h>
#define VUELTAS 1000000
static long contador = 0;

static void *sumar(void *arg) {
    (void)arg;
    for (int i = 0; i < VUELTAS; i++) contador++;
    return NULL;
}

int main(void) {
    pthread_t a, b;
    pthread_create(&a, NULL, sumar, NULL);
    pthread_create(&b, NULL, sumar, NULL);
    pthread_join(a, NULL);
    pthread_join(b, NULL);
    printf("esperado %d, obtenido %ld\n", 2 * VUELTAS, contador);
    return 0;
}
